sp_widget.client_script:
api.controller = function($scope, $timeout, $sce) {

    var c = this;

    var MAX_SIZE = 5 * 1024 * 1024;
    var ALLOWED = /\.(pdf|jpg|jpeg|png|gif|webp|bmp|doc|docx|xls|xlsx|csv|ppt|pptx|txt)$/i;


    /* =========================================================
       BASIC DATA
       ========================================================= */

    c.documents = [];
    c.filteredDocuments = [];
    c.searchText = "";
    c.studentName = "Student";
    c.totalDocuments = 0;
    c.message = "";

    c.loading = false;
    c.uploading = false;
    c.downloadingId = "";

    c.uploadError = "";
    c.uploadSuccess = "";

    c.showUploadModal = false;
    c.showPreviewModal = false;
    c.selectedDocument = null;

    /* preview state */
    c.previewLoading = false;
    c.previewError = "";
    c.previewKind = "";
    c.previewImage = "";
    c.previewFrame = null;
    c.previewText = "";

    /* delete state */
    c.showDeleteModal = false;
    c.deleteTarget = null;
    c.deleting = false;
    c.deleteError = "";

    var previewToken = 0;
    var previewBlobUrl = "";


    /* =========================================================
       UPLOAD OBJECT
       ========================================================= */

    c.upload = {
        documentType: "",
        customDocumentType: "",
        description: "",
        file: null,
        fileName: "",
        fileType: "",
        fileData: "",
        fileSize: 0,
        fileSelected: false
    };


    /* =========================================================
       LOAD DATA FROM SERVER
       ========================================================= */

    function applySearch() {

        var query = String(c.searchText || "").toLowerCase().trim();

        if (!query) {
            c.filteredDocuments = c.documents.slice();
            return;
        }

        var words = query.split(/\s+/);

        c.filteredDocuments = c.documents.filter(function(doc) {

            var text = [
                doc.title,
                doc.documentType,
                doc.description,
                doc.fileName,
                doc.uploadedDate
            ].join(" ").toLowerCase();

            /* every word typed must be found somewhere in the document */
            return words.every(function(word) {
                return text.indexOf(word) !== -1;
            });
        });
    }

    c.applySearch = applySearch;

    c.clearSearch = function() {
        c.searchText = "";
        applySearch();
    };


    function loadData() {

        if (!c.data) {
            return;
        }

        c.documents = angular.isArray(c.data.documents) ? c.data.documents : [];
        c.studentName = c.data.studentName || "Student";
        c.totalDocuments = c.documents.length;
        c.message = c.data.message || "";

        applySearch();

        if (c.data.uploadError) {
            c.uploadError = c.data.uploadError;
            c.data.uploadError = "";
        }
    }

    loadData();


    /* =========================================================
       OPEN / CLOSE UPLOAD MODAL
       ========================================================= */

    c.openUploadModal = function() {

        c.uploadError = "";
        c.uploadSuccess = "";
        c.resetUpload();
        c.showUploadModal = true;

        $timeout(function() {
            var input = document.getElementById("nxDocumentFile");
            if (input) {
                input.value = "";
            }
        }, 100);
    };

    c.closeUploadModal = function() {

        if (c.uploading) {
            return;
        }

        c.showUploadModal = false;
        c.resetUpload();
        c.uploadError = "";
    };


    /* =========================================================
       RESET UPLOAD FORM
       ========================================================= */

    c.resetUpload = function() {

        c.upload.documentType = "";
        c.upload.customDocumentType = "";
        c.upload.description = "";

        c.removeSelectedFile();
    };


    /* =========================================================
       FILE SELECTED (called from the input's onchange)
       ========================================================= */

    c.fileSelected = function(file) {

        c.uploadError = "";

        if (!file) {
            $scope.$applyAsync();
            return;
        }

        /* Size */
        if (file.size > MAX_SIZE) {
            c.uploadError = "File size must not exceed 5 MB.";
            c.removeSelectedFile();
            $scope.$applyAsync();
            return;
        }

        /* Format */
        if (!ALLOWED.test(file.name)) {
            c.uploadError = "This file format is not supported.";
            c.removeSelectedFile();
            $scope.$applyAsync();
            return;
        }

        /* Store file */
        c.upload.file = file;
        c.upload.fileName = file.name;
        c.upload.fileType = file.type || "application/octet-stream";
        c.upload.fileSize = file.size;
        c.upload.fileData = "";
        c.upload.fileSelected = true;

        /* Show the "File selected" box immediately */
        $scope.$applyAsync();

        /* Convert to base64 */
        var reader = new FileReader();

        reader.onload = function(event) {
            c.upload.fileData = event.target.result;
            $scope.$applyAsync();
        };

        reader.onerror = function() {
            c.uploadError = "Unable to read the selected file.";
            c.removeSelectedFile();
            $scope.$applyAsync();
        };

        reader.readAsDataURL(file);
    };


    /* =========================================================
       REMOVE SELECTED FILE
       ========================================================= */

    c.removeSelectedFile = function() {

        c.upload.file = null;
        c.upload.fileName = "";
        c.upload.fileType = "";
        c.upload.fileData = "";
        c.upload.fileSize = 0;
        c.upload.fileSelected = false;

        var input = document.getElementById("nxDocumentFile");

        if (input) {
            input.value = "";
        }
    };


    /* =========================================================
       VALIDATE UPLOAD
       ========================================================= */

    c.validateUpload = function() {

        c.uploadError = "";

        if (!c.upload.documentType) {
            c.uploadError = "Please select a document.";
            return false;
        }

        if (c.upload.documentType === "Other" &&
            !(c.upload.customDocumentType || "").trim()) {
            c.uploadError = "Please specify the document.";
            return false;
        }

        if (!c.upload.description || !c.upload.description.trim()) {
            c.uploadError = "Please enter a description.";
            return false;
        }

        if (!c.upload.file || !c.upload.fileSelected) {
            c.uploadError = "Please select a file.";
            return false;
        }

        if (!c.upload.fileData) {
            c.uploadError = "Please wait until the file is ready.";
            return false;
        }

        return true;
    };


    /* =========================================================
       UPLOAD DOCUMENT
       ========================================================= */

    c.uploadDocument = function() {

        if (c.uploading) {
            return;
        }

        if (!c.validateUpload()) {
            return;
        }

        c.uploading = true;
        c.uploadError = "";
        c.uploadSuccess = "";

        var finalDocumentType = c.upload.documentType;

        if (finalDocumentType === "Other") {
            finalDocumentType = c.upload.customDocumentType.trim();
        }

        c.server.get({
            action: "save_document",
            document_type: finalDocumentType,
            description: c.upload.description.trim(),
            file_name: c.upload.fileName,
            file_type: c.upload.fileType,
            file_data: c.upload.fileData
        }).then(

            function(response) {

                c.uploading = false;

                if (!response || !response.data) {
                    c.uploadError = "No response received from server.";
                    return;
                }

                c.data = response.data;

                /* Server error */
                if (c.data.uploadError) {
                    c.uploadError = c.data.uploadError;
                    return;
                }

                /* Success: server already returned the refreshed list */
                if (c.data.uploadSuccess) {

                    c.searchText = "";
                    loadData();

                    c.uploadSuccess = "Document uploaded successfully.";
                    c.showUploadModal = false;
                    c.resetUpload();

                    $timeout(function() {
                        c.uploadSuccess = "";
                    }, 4000);

                    return;
                }

                /* Fallback */
                loadData();
            },

            function(error) {

                c.uploading = false;
                console.error("NEXORA DOCUMENT UPLOAD ERROR:", error);
                c.uploadError = "Unable to upload document.";
            }
        );
    };


    /* =========================================================
       REFRESH DOCUMENTS
       ========================================================= */

    c.refreshDocuments = function() {

        if (c.loading) {
            return;
        }

        c.loading = true;
        c.uploadError = "";

        c.server.get({
            action: "load_documents"
        }).then(

            function(response) {

                c.loading = false;

                if (response && response.data) {
                    c.data = response.data;
                    loadData();
                }
            },

            function(error) {

                c.loading = false;
                console.error("NEXORA REFRESH ERROR:", error);
                c.uploadError = "Unable to refresh documents.";
            }
        );
    };


    /* =========================================================
       PREVIEW / CLOSE PREVIEW
       The file is read on the server and shown inside the modal.
       ========================================================= */

    var IMAGE_TYPES = {
        jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png",
        gif: "image/gif", webp: "image/webp", bmp: "image/bmp"
    };

    function getExtension(fileName) {
        var name = String(fileName || "").toLowerCase();
        var i = name.lastIndexOf(".");
        return i === -1 ? "" : name.substring(i + 1);
    }

    function getPreviewKind(doc) {

        var ext = getExtension(doc.fileName);

        if (IMAGE_TYPES[ext]) { return "image"; }
        if (ext === "pdf")    { return "pdf"; }
        if (ext === "txt" || ext === "csv") { return "text"; }

        return "none";   /* Word / Excel / PowerPoint cannot be previewed in a browser */
    }

    function base64ToText(base64) {

        var binary = atob(base64);

        try {
            return decodeURIComponent(escape(binary));
        } catch (e) {
            return binary;
        }
    }

    function releasePreview() {

        if (previewBlobUrl) {
            window.URL.revokeObjectURL(previewBlobUrl);
            previewBlobUrl = "";
        }

        c.previewLoading = false;
        c.previewError = "";
        c.previewKind = "";
        c.previewImage = "";
        c.previewFrame = null;
        c.previewText = "";
    }

    c.previewDocument = function(doc) {

        if (!doc) {
            return;
        }

        if (!doc.hasAttachment) {
            c.uploadError = "Preview is not available.";
            return;
        }

        releasePreview();

        var token = ++previewToken;

        c.selectedDocument = doc;
        c.previewKind = getPreviewKind(doc);
        c.showPreviewModal = true;

        /* Types that cannot be previewed: the modal explains it, nothing to load */
        if (c.previewKind === "none") {
            return;
        }

        c.previewLoading = true;

        c.server.get({
            action: "get_file",
            doc_id: doc.sysId
        }).then(

            function(response) {

                /* the modal was closed or another preview was opened meanwhile */
                if (token !== previewToken) {
                    return;
                }

                c.previewLoading = false;

                var d = response && response.data;

                if (!d || d.fileError || !d.file) {
                    c.previewError = (d && d.fileError) || "Unable to load the preview.";
                    return;
                }

                try {

                    if (c.previewKind === "image") {

                        var ext = getExtension(doc.fileName);
                        var imgType = (d.file.type && d.file.type.indexOf("image/") === 0)
                            ? d.file.type
                            : IMAGE_TYPES[ext];

                        c.previewImage = "data:" + imgType + ";base64," + d.file.data;

                    } else if (c.previewKind === "pdf") {

                        var blob = base64ToBlob(d.file.data, "application/pdf");
                        previewBlobUrl = window.URL.createObjectURL(blob);
                        c.previewFrame = $sce.trustAsResourceUrl(previewBlobUrl);

                    } else if (c.previewKind === "text") {

                        c.previewText = base64ToText(d.file.data);
                    }

                } catch (err) {
                    console.error("NEXORA PREVIEW ERROR:", err);
                    c.previewError = "Unable to display this file.";
                }
            },

            function(error) {

                if (token !== previewToken) {
                    return;
                }

                c.previewLoading = false;
                console.error("NEXORA PREVIEW ERROR:", error);
                c.previewError = "Unable to load the preview.";
            }
        );
    };

    c.closePreview = function() {

        previewToken++;
        releasePreview();

        c.showPreviewModal = false;
        c.selectedDocument = null;
    };


    /* =========================================================
       DELETE DOCUMENT
       ========================================================= */

    c.confirmDelete = function(doc) {

        if (!doc) {
            return;
        }

        c.deleteTarget = doc;
        c.deleteError = "";
        c.showDeleteModal = true;
    };

    c.closeDeleteModal = function() {

        if (c.deleting) {
            return;
        }

        c.showDeleteModal = false;
        c.deleteTarget = null;
        c.deleteError = "";
    };

    c.deleteDocument = function() {

        if (c.deleting || !c.deleteTarget) {
            return;
        }

        c.deleting = true;
        c.deleteError = "";

        c.server.get({
            action: "delete_document",
            doc_id: c.deleteTarget.sysId
        }).then(

            function(response) {

                c.deleting = false;

                if (!response || !response.data) {
                    c.deleteError = "No response received from server.";
                    return;
                }

                if (response.data.deleteError) {
                    c.deleteError = response.data.deleteError;
                    return;
                }

                if (response.data.deleteSuccess) {

                    /* Server returned the refreshed list */
                    c.data = response.data;
                    loadData();

                    c.showDeleteModal = false;
                    c.deleteTarget = null;

                    c.uploadError = "";
                    c.uploadSuccess = "Document deleted successfully.";

                    $timeout(function() {
                        c.uploadSuccess = "";
                    }, 4000);

                    return;
                }

                c.deleteError = "Unable to delete the document.";
            },

            function(error) {

                c.deleting = false;
                console.error("NEXORA DELETE ERROR:", error);
                c.deleteError = "Unable to delete the document.";
            }
        );
    };


    function base64ToBlob(base64, type) {

        var binary = atob(base64);
        var bytes = new Uint8Array(binary.length);

        for (var i = 0; i < binary.length; i++) {
            bytes[i] = binary.charCodeAt(i);
        }

        return new Blob([bytes], { type: type || "application/octet-stream" });
    }

    c.downloadDocument = function(doc) {

        if (!doc) {
            return;
        }

        if (!doc.hasAttachment) {
            c.uploadError = "Download is not available.";
            return;
        }

        if (c.downloadingId) {
            return;
        }

        c.downloadingId = doc.sysId;
        c.uploadError = "";

        /* The server reads the file and sends it back as base64 */
        c.server.get({
            action: "get_file",
            doc_id: doc.sysId
        }).then(

            function(response) {

                c.downloadingId = "";

                var d = response && response.data;

                if (!d || d.fileError || !d.file) {
                    c.uploadError = (d && d.fileError) || "Unable to download the file.";
                    return;
                }

                try {
                    var blob = base64ToBlob(d.file.data, d.file.type);
                    var url = window.URL.createObjectURL(blob);

                    var link = document.createElement("a");
                    link.href = url;
                    link.download = d.file.name || doc.fileName || "document";
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);

                    setTimeout(function() {
                        window.URL.revokeObjectURL(url);
                    }, 1500);

                } catch (err) {
                    console.error("NEXORA DOWNLOAD ERROR:", err);
                    c.uploadError = "Unable to download the file.";
                }
            },

            function(error) {

                c.downloadingId = "";
                console.error("NEXORA DOWNLOAD ERROR:", error);
                c.uploadError = "Unable to download the file.";
            }
        );
    };


    /* =========================================================
       FILE ICON
       ========================================================= */

    c.getFileIcon = function(doc) {

        if (!doc) {
            return "fa-file-o";
        }

        var type = String(doc.fileType || "").toUpperCase();

        if (type === "PDF")   { return "fa-file-pdf-o"; }
        if (type === "IMAGE") { return "fa-file-image-o"; }
        if (type === "DOC")   { return "fa-file-word-o"; }
        if (type === "XLS")   { return "fa-file-excel-o"; }
        if (type === "PPT")   { return "fa-file-powerpoint-o"; }

        return "fa-file-o";
    };


    /* =========================================================
       CLOSE MODAL BY BACKDROP
       ========================================================= */

    c.closeModalFromBackdrop = function(event) {

        if (event && event.target !== event.currentTarget) {
            return;
        }

        if (!c.uploading) {
            c.closeUploadModal();
        }
    };


    /* =========================================================
       ESCAPE KEY
       ========================================================= */

    var keyHandler = function(event) {

        if (event.key !== "Escape") {
            return;
        }

        if (c.showDeleteModal) {
            $scope.$applyAsync(function() {
                c.closeDeleteModal();
            });
            return;
        }

        if (c.showPreviewModal) {
            $scope.$applyAsync(function() {
                c.closePreview();
            });
            return;
        }

        if (c.showUploadModal && !c.uploading) {
            $scope.$applyAsync(function() {
                c.closeUploadModal();
            });
        }
    };

    document.addEventListener("keydown", keyHandler);


    /* =========================================================
       CLEANUP
       ========================================================= */

    $scope.$on("$destroy", function() {
        document.removeEventListener("keydown", keyHandler);
        releasePreview();
    });

};

sp_widget.css:
/* =========================================================
   NEXORA STUDENT DOCUMENT CENTER
   COMPLETE DASHBOARD CSS
   ========================================================= */


/* =========================================================
   GLOBAL PAGE
   ========================================================= */

.nx-documents-page {
    width: 85vw;
    min-height: 100vh;

    margin: 0 auto;
    padding: 70px;

    box-sizing: border-box;

    background: #ffffff;

    font-family: "Inter", "Segoe UI", Arial, sans-serif;

    color: #102a43;
}


/* =========================================================
   HERO SECTION
   ========================================================= */

.nx-hero {
    position: relative;

    display: flex;
    align-items: center;
    justify-content: space-between;

    min-height: 190px;

    padding: 38px 44px;

    margin-bottom: 42px;

    border-radius: 20px;

    background:
        linear-gradient(
            135deg,
            #081c35 0%,
            #0c2b4e 55%,
            #123c65 100%
        );

    color: #ffffff;

    overflow: hidden;

    box-shadow: none;

    box-sizing: border-box;
}


/* Decorative circle */

.nx-hero:after {
    content: "";

    position: absolute;

    width: 280px;
    height: 280px;

    right: -80px;
    top: -100px;

    border-radius: 50%;

    background: rgba(255,255,255,0.05);

    pointer-events: none;
}


/* Hero left content */

.nx-hero-left {
    position: relative;

    z-index: 2;
}


/* Small title */

.nx-kicker {
    margin-bottom: 10px;

    color: #ff806d;

    font-size: 12px;
    font-weight: 800;

    letter-spacing: 2px;

    text-transform: uppercase;
}


/* Hero heading */

.nx-hero h1 {
    margin: 0 0 10px;

    color: #ffffff;

    font-size: 32px;
    font-weight: 750;

    line-height: 1.2;
}


/* Hero description */

.nx-hero p {
    margin: 0;

    max-width: 620px;

    color: #cbd9e8;

    font-size: 15px;

    line-height: 1.6;
}


/* Hero icon */

.nx-hero-icon {
    position: relative;

    z-index: 2;

    width: 82px;
    height: 82px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border-radius: 22px;

    background: rgba(255,255,255,0.10);

    color: #ff806d;

    font-size: 36px;

    backdrop-filter: blur(10px);
}


.nx-hero-upload {
    margin-top: 20px;
}


/* =========================================================
   ALERTS
   ========================================================= */

.nx-alert {
    display: flex;

    align-items: center;

    gap: 12px;

    padding: 14px 18px;

    margin-bottom: 18px;

    border-radius: 12px;

    font-size: 14px;

    box-sizing: border-box;
}


.nx-alert-success {
    background: #ecfdf3;

    color: #147a48;

    border: 1px solid #b8efd1;
}


.nx-alert-error {
    background: #fff1f0;

    color: #b42318;

    border: 1px solid #ffd0cc;
}


.nx-alert-error button {
    margin-left: auto;

    border: 0;

    background: transparent;

    color: inherit;

    cursor: pointer;
}


/* =========================================================
   MAIN DOCUMENT SECTION
   ========================================================= */

.nx-document-section {
    width: 100%;

    background: #ffffff;

    border-radius: 20px;

    padding: 0;

    box-shadow: none;

    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
   ========================================================= */

.nx-section-header {
    display: flex;

    align-items: center;
    justify-content: space-between;

    gap: 20px;

    padding: 0 0 24px;

    border-bottom: 1px solid #e9eef5;
}


.nx-section-header h2 {
    margin: 0 0 7px;

    color: #102a43;

    font-size: 24px;
    font-weight: 750;

    line-height: 1.3;
}


.nx-section-header p {
    margin: 0;

    color: #718096;

    font-size: 14px;
}


.nx-header-actions {
    display: flex;

    align-items: center;

    gap: 10px;

    flex-shrink: 0;
}


/* =========================================================
   GENERAL BUTTONS
   ========================================================= */

.nx-upload-btn,
.nx-submit-btn {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 8px;

    border: 0;

    border-radius: 10px;

    background: #ff725f;

    color: #ffffff;

    padding: 12px 18px;

    font-size: 13px;
    font-weight: 700;

    cursor: pointer;

    white-space: nowrap;

    transition:
        background 0.2s ease,
        transform 0.2s ease;
}


.nx-upload-btn:hover,
.nx-submit-btn:hover {
    background: #ee5f4d;

    transform: translateY(-1px);
}


.nx-submit-btn:disabled {
    opacity: 0.7;

    cursor: not-allowed;
}


/* =========================================================
   REFRESH BUTTON
   ========================================================= */

.nx-refresh-btn {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    border: 1px solid #d9e2ec;

    border-radius: 10px;

    padding: 11px 15px;

    background: #ffffff;

    color: #334e68;

    font-size: 13px;
    font-weight: 650;

    cursor: pointer;

    white-space: nowrap;

    transition:
        background 0.2s ease,
        border-color 0.2s ease;
}


.nx-refresh-btn:hover {
    background: #f6f8fb;

    border-color: #c9d5e1;
}


.nx-refresh-btn:disabled {
    opacity: 0.6;

    cursor: not-allowed;
}


/* =========================================================
   LOADING SPINNER
   ========================================================= */

.nx-spin {
    animation: nxSpin 1s linear infinite;
}


@keyframes nxSpin {

    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }

}


/* =========================================================
   SEARCH + COUNT TOOLBAR
   ========================================================= */

.nx-toolbar {
    position: relative;

    width: 100%;

    min-height: 54px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 10px;

    margin: 22px 0 18px;

    padding: 0;

    box-sizing: border-box;
}


/* =========================================================
   SEARCH CONTAINER
   ========================================================= */

.nx-search {
    position: relative;

    width: 460px;

    max-width: 460px;

    min-width: 200px;

    flex: 0 1 460px;

    margin: 0;

    padding: 0;

    box-sizing: border-box;
}


/* =========================================================
   SEARCH ICON
   ========================================================= */

.nx-search-icon {
    position: absolute;

    left: 14px;

    top: 50%;

    transform: translateY(-50%);

    color: #8a9aad;

    font-size: 13px;

    pointer-events: none;

    z-index: 2;
}


/* =========================================================
   SEARCH INPUT
   ========================================================= */

.nx-search-input {
    display: block;

    width: 100%;

    height: 42px;

    box-sizing: border-box;

    padding: 11px 38px;

    border: 1px solid #d7e0e9;

    border-radius: 10px;

    background: #ffffff;

    color: #243b53;

    font-family: "Inter", "Segoe UI", Arial, sans-serif;

    font-size: 13px;

    line-height: 20px;

    outline: none;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-search-input::placeholder {
    color: #8a9aad;

    opacity: 1;
}


.nx-search-input:focus {
    border-color: #5d8fbd;

    box-shadow:
        0 0 0 3px rgba(93,143,189,0.12);
}


/* =========================================================
   CLEAR SEARCH BUTTON
   ========================================================= */

.nx-search-clear {
    position: absolute;

    right: 8px;

    top: 50%;

    transform: translateY(-50%);

    width: 24px;

    height: 24px;

    display: flex;

    align-items: center;
    justify-content: center;

    border: 0;

    border-radius: 50%;

    background: #eef2f6;

    color: #607287;

    font-size: 11px;

    cursor: pointer;

    z-index: 3;
}


.nx-search-clear:hover {
    background: #dfe6ee;

    color: #334e68;
}


/* =========================================================
   SEARCH BUTTON
   ========================================================= */

.nx-search-btn {
    height: 42px;

    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    flex: 0 0 auto;

    box-sizing: border-box;

    padding: 11px 18px;

    border: 0;

    border-radius: 10px;

    background: #102a43;

    color: #ffffff;

    font-family: "Inter", "Segoe UI", Arial, sans-serif;

    font-size: 13px;

    font-weight: 700;

    line-height: 20px;

    cursor: pointer;

    white-space: nowrap;

    transition:
        background 0.2s ease,
        transform 0.2s ease;
}


.nx-search-btn:hover {
    background: #1b3d5e;

    transform: translateY(-1px);
}


/* =========================================================
   DOCUMENT COUNT
   ========================================================= */

.nx-document-count {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 7px;

    min-height: 30px;

    padding: 7px 12px;

    box-sizing: border-box;

    border-radius: 20px;

    background: #edf5ff;

    color: #285f9e;

    font-size: 12px;

    font-weight: 700;

    white-space: nowrap;
}


/* Keep count on RIGHT */

.nx-toolbar .nx-document-count {
    position: absolute;

    right: 0;

    top: 50%;

    transform: translateY(-50%);

    margin: 0;
}


/* =========================================================
   NO SEARCH RESULTS
   ========================================================= */

.nx-no-results {
    padding: 50px 20px;

    text-align: center;
}


.nx-no-results > i {
    display: block;

    margin-bottom: 14px;

    color: #8ba0b5;

    font-size: 34px;
}


.nx-no-results h3 {
    margin: 0 0 7px;

    color: #334e68;

    font-size: 18px;
}


.nx-no-results p {
    margin: 0 0 16px;

    color: #8a9aad;

    font-size: 13px;
}


/* =========================================================
   DOCUMENT GRID
   ========================================================= */

.nx-document-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 20px;

    margin-top: 22px;

    width: 100%;
}


.nx-toolbar + .nx-document-grid {
    margin-top: 18px;
}


.nx-document-count + .nx-document-grid {
    margin-top: 0;
}


/* =========================================================
   DOCUMENT CARD
   ========================================================= */

.nx-document-card {
    display: flex;

    flex-direction: column;

    min-width: 0;

    border: 1px solid #e7edf4;

    border-radius: 16px;

    background: #ffffff;

    overflow: hidden;

    box-sizing: border-box;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        border-color 0.2s ease;
}


.nx-document-card:hover {
    transform: translateY(-3px);

    border-color: #d5e0ec;

    box-shadow:
        0 14px 30px rgba(15,23,42,0.09);
}


/* =========================================================
   CARD TOP
   ========================================================= */

.nx-card-top {
    display: flex;

    align-items: center;
    justify-content: space-between;

    padding: 20px 20px 12px;

    gap: 12px;
}


/* =========================================================
   FILE ICON
   ========================================================= */

.nx-file-icon {
    width: 50px;

    height: 50px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border-radius: 13px;

    background: #eef4fa;

    color: #245b8f;

    font-size: 23px;
}


.nx-file-pdf {
    background: #fff0ef;

    color: #d64235;
}


.nx-file-image {
    background: #edf8f3;

    color: #21875a;
}


.nx-file-doc {
    background: #edf4ff;

    color: #2868bd;
}


.nx-file-xls {
    background: #ecf8f0;

    color: #21854f;
}


.nx-file-ppt {
    background: #fff4ec;

    color: #d56a25;
}


/* =========================================================
   DOCUMENT TYPE
   ========================================================= */

.nx-document-type {
    display: inline-block;

    max-width: 150px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;

    padding: 6px 9px;

    border-radius: 20px;

    background: #f5f7fa;

    color: #607287;

    font-size: 10px;

    font-weight: 750;

    text-transform: uppercase;

    letter-spacing: 0.4px;
}


/* =========================================================
   CARD CONTENT
   ========================================================= */

.nx-card-content {
    padding: 5px 20px 18px;

    flex: 1;
}


.nx-card-content h3 {
    margin: 0 0 8px;

    color: #102a43;

    font-size: 17px;

    font-weight: 750;

    line-height: 1.35;

    white-space: nowrap;

    overflow: hidden;

    text-overflow: ellipsis;
}


.nx-description {
    margin: 0 0 16px;

    min-height: 42px;

    color: #718096;

    font-size: 13px;

    line-height: 1.55;

    display: -webkit-box;

    -webkit-line-clamp: 2;

    -webkit-box-orient: vertical;

    overflow: hidden;
}


.nx-no-description {
    color: #a0aec0;

    font-style: italic;
}


/* =========================================================
   CARD META
   ========================================================= */

.nx-card-meta {
    display: flex;

    flex-wrap: wrap;

    gap: 12px;

    color: #8a9aad;

    font-size: 11px;
}


.nx-card-meta span {
    display: inline-flex;

    align-items: center;

    gap: 5px;
}


/* =========================================================
   CARD ACTIONS
   ========================================================= */

.nx-card-actions {
    display: grid;

    grid-template-columns:
        1fr 1fr 40px;

    gap: 8px;

    padding: 13px 16px;

    border-top: 1px solid #edf1f5;

    background: #fafbfd;

    box-sizing: border-box;
}


/* Preview + Download */

.nx-preview-btn,
.nx-download-btn {
    display: flex;

    align-items: center;
    justify-content: center;

    gap: 6px;

    min-height: 36px;

    padding: 9px;

    border-radius: 8px;

    font-size: 12px;

    font-weight: 700;

    cursor: pointer;

    box-sizing: border-box;
}


.nx-preview-btn {
    border: 1px solid #dbe4ed;

    background: #ffffff;

    color: #36546d;
}


.nx-preview-btn:hover {
    background: #f7f9fb;
}


.nx-download-btn {
    border: 0;

    background: #102a43;

    color: #ffffff;
}


.nx-download-btn:hover {
    background: #1b3d5e;
}


.nx-preview-btn:disabled,
.nx-download-btn:disabled {
    opacity: 0.45;

    cursor: not-allowed;
}


/* =========================================================
   DELETE BUTTON
   ========================================================= */

.nx-delete-btn {
    display: flex;

    align-items: center;
    justify-content: center;

    min-height: 36px;

    padding: 9px 0;

    border: 1px solid #f3c9c4;

    border-radius: 8px;

    background: #fff5f4;

    color: #d64235;

    font-size: 13px;

    cursor: pointer;
}


.nx-delete-btn:hover {
    background: #ffe4e1;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.nx-empty-state {
    padding: 70px 20px;

    text-align: center;
}


.nx-empty-icon {
    width: 70px;

    height: 70px;

    margin: 0 auto 18px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 18px;

    background: #f1f5f9;

    color: #8ba0b5;

    font-size: 30px;
}


.nx-empty-state h3 {
    margin: 0 0 7px;

    color: #334e68;

    font-size: 18px;
}


.nx-empty-state p {
    margin: 0;

    color: #8a9aad;

    font-size: 13px;
}


.nx-empty-state p.nx-empty-message {
    margin-top: 10px;

    color: #b42318;

    font-size: 12px;
}


/* =========================================================
   MODAL OVERLAY
   ========================================================= */

.nx-modal-overlay {
    position: fixed;

    top: 0;
    right: 0;
    bottom: 0;
    left: 0;

    z-index: 9999;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 20px;

    background: rgba(7,20,35,0.68);

    backdrop-filter: blur(5px);

    box-sizing: border-box;
}


/* =========================================================
   UPLOAD MODAL
   ========================================================= */

.nx-modal {
    width: 100%;

    max-width: 650px;

    max-height: 92vh;

    display: flex;

    flex-direction: column;

    border-radius: 18px;

    background: #ffffff;

    box-shadow:
        0 30px 80px rgba(0,0,0,0.25);

    overflow: hidden;
}


/* =========================================================
   MODAL HEADER
   ========================================================= */

.nx-modal-header {
    display: flex;

    justify-content: space-between;

    gap: 20px;

    padding: 24px 26px;

    border-bottom: 1px solid #e8edf3;
}


.nx-modal-header h2 {
    margin: 0 0 6px;

    color: #102a43;

    font-size: 21px;
}


.nx-modal-header p {
    margin: 0;

    color: #718096;

    font-size: 12px;
}


.nx-modal-close {
    width: 36px;

    height: 36px;

    flex-shrink: 0;

    border: 0;

    border-radius: 9px;

    background: #f3f6f9;

    color: #607287;

    cursor: pointer;
}


.nx-modal-close:hover {
    background: #e8edf3;
}


.nx-modal-body {
    padding: 25px 26px;

    overflow-y: auto;
}


/* =========================================================
   FORM
   ========================================================= */

.nx-form-group {
    position: relative;

    margin-bottom: 19px;
}


.nx-form-group > label {
    display: block;

    margin-bottom: 7px;

    color: #334e68;

    font-size: 13px;

    font-weight: 700;
}


.nx-form-group > label span {
    color: #e85d4a;
}


.nx-form-control {
    width: 100%;

    box-sizing: border-box;

    border: 1px solid #d7e0e9;

    border-radius: 9px;

    padding: 11px 13px;

    background: #ffffff;

    color: #243b53;

    font-size: 13px;

    outline: none;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-form-control:focus {
    border-color: #5d8fbd;

    box-shadow:
        0 0 0 3px rgba(93,143,189,0.12);
}


.nx-textarea {
    resize: vertical;

    min-height: 90px;
}


/* =========================================================
   FILE INPUT
   ========================================================= */

.nx-real-file-input {
    position: absolute;

    width: 1px;

    height: 1px;

    padding: 0;

    margin: -1px;

    overflow: hidden;

    clip: rect(0,0,0,0);

    white-space: nowrap;

    border: 0;
}


/* =========================================================
   FILE SELECT
   ========================================================= */

label.nx-file-select {
    width: 100%;

    min-height: 125px;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 7px;

    margin-bottom: 0;

    box-sizing: border-box;

    border: 1.5px dashed #bdcad7;

    border-radius: 12px;

    background: #fafcfe;

    color: #486581;

    cursor: pointer;
}


label.nx-file-select:hover {
    border-color: #6f9fc7;

    background: #f3f8fc;
}


label.nx-file-select i {
    color: #5e8db8;

    font-size: 27px;
}


label.nx-file-select span {
    color: #486581;

    font-size: 13px;

    font-weight: 750;
}


label.nx-file-select small {
    color: #8a9aad;

    font-size: 10px;

    text-align: center;
}


/* =========================================================
   SELECTED FILE
   ========================================================= */

.nx-file-selected {
    display: flex;

    align-items: center;

    gap: 12px;

    padding: 14px;

    border: 1px solid #bfe8d0;

    border-radius: 11px;

    background: #f0fbf5;
}


.nx-selected-icon {
    width: 40px;

    height: 40px;

    display: flex;

    align-items: center;
    justify-content: center;

    flex-shrink: 0;

    border-radius: 10px;

    background: #d8f4e4;

    color: #218653;
}


.nx-selected-content {
    display: flex;

    flex-direction: column;

    gap: 3px;

    flex: 1;

    min-width: 0;
}


.nx-selected-content strong {
    color: #1f5138;

    font-size: 13px;
}


.nx-selected-content span {
    color: #5d806d;

    font-size: 11px;

    overflow: hidden;

    text-overflow: ellipsis;

    white-space: nowrap;
}


.nx-delete-file {
    display: inline-flex;

    align-items: center;

    gap: 5px;

    border: 0;

    background: transparent;

    color: #c44d43;

    font-size: 11px;

    font-weight: 700;

    cursor: pointer;
}


.nx-file-help {
    display: block;

    margin-top: 7px;

    color: #8a9aad;

    font-size: 10px;
}


/* =========================================================
   MODAL ERROR
   ========================================================= */

.nx-modal-error {
    display: flex;

    align-items: flex-start;

    gap: 10px;

    margin: 0 26px 14px;

    padding: 11px 14px;

    border: 1px solid #ffd0cc;

    border-radius: 10px;

    background: #fff1f0;

    color: #b42318;

    font-size: 12px;

    line-height: 1.5;
}


/* =========================================================
   MODAL FOOTER
   ========================================================= */

.nx-modal-footer {
    display: flex;

    align-items: center;

    justify-content: flex-end;

    gap: 10px;

    padding: 17px 26px;

    border-top: 1px solid #e8edf3;

    background: #fafbfd;
}


.nx-cancel-btn {
    padding: 11px 18px;

    border: 1px solid #d5dfe8;

    border-radius: 9px;

    background: #ffffff;

    color: #52687d;

    font-size: 12px;

    font-weight: 700;

    cursor: pointer;
}


.nx-cancel-btn:hover {
    background: #f4f7fa;
}


/* =========================================================
   PREVIEW MODAL
   ========================================================= */

.nx-preview-modal {
    width: 100%;

    max-width: 1000px;

    height: 88vh;

    display: flex;

    flex-direction: column;

    border-radius: 16px;

    background: #ffffff;

    overflow: hidden;

    box-shadow:
        0 30px 80px rgba(0,0,0,0.30);
}


.nx-preview-header {
    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    padding: 17px 22px;

    border-bottom: 1px solid #e5eaf0;
}


.nx-preview-header h2 {
    margin: 0 0 5px;

    color: #102a43;

    font-size: 17px;
}


.nx-preview-header span {
    color: #718096;

    font-size: 11px;
}


.nx-preview-body {
    position: relative;

    flex: 1;

    background: #edf1f5;

    overflow: auto;
}


.nx-preview-frame {
    width: 100%;

    height: 100%;

    border: 0;

    background: #ffffff;
}


.nx-preview-footer {
    display: flex;

    justify-content: flex-end;

    gap: 10px;

    padding: 13px 20px;

    border-top: 1px solid #e5eaf0;

    background: #ffffff;
}


/* =========================================================
   PREVIEW STATES
   ========================================================= */

.nx-preview-state {
    height: 100%;

    display: flex;

    flex-direction: column;

    align-items: center;
    justify-content: center;

    gap: 6px;

    padding: 20px;

    text-align: center;

    color: #607287;
}


.nx-preview-state i {
    font-size: 40px;

    color: #8ba0b5;

    margin-bottom: 8px;
}


.nx-preview-state p {
    margin: 0;

    font-size: 14px;
}


.nx-preview-state .nx-preview-hint {
    font-size: 12px;

    color: #8a9aad;
}


.nx-preview-error,
.nx-preview-error i {
    color: #b42318;
}


/* =========================================================
   PREVIEW IMAGE
   ========================================================= */

.nx-preview-image-wrap {
    min-height: 100%;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 16px;

    box-sizing: border-box;
}


.nx-preview-image {
    max-width: 100%;

    max-height: calc(88vh - 150px);

    border-radius: 8px;

    background: #ffffff;

    box-shadow:
        0 6px 24px rgba(15,23,42,0.15);
}


.nx-preview-text {
    margin: 0;

    padding: 20px;

    background: #ffffff;

    color: #243b53;

    font-size: 12px;

    line-height: 1.6;

    white-space: pre-wrap;

    word-break: break-word;

    min-height: 100%;

    box-sizing: border-box;
}


/* =========================================================
   DELETE CONFIRM MODAL
   ========================================================= */

.nx-confirm-modal {
    max-width: 440px;
}


.nx-confirm-body {
    padding: 30px 28px 18px;

    text-align: center;
}


.nx-confirm-icon {
    width: 58px;

    height: 58px;

    margin: 0 auto 16px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 16px;

    background: #fff1f0;

    color: #d64235;

    font-size: 24px;
}


.nx-confirm-body h2 {
    margin: 0 0 10px;

    color: #102a43;

    font-size: 20px;
}


.nx-confirm-body p {
    margin: 0;

    color: #607287;

    font-size: 13px;

    line-height: 1.6;
}


.nx-confirm-body strong {
    color: #102a43;
}


.nx-modal-error.nx-confirm-error {
    margin: 16px 0 0;

    text-align: left;
}


/* =========================================================
   DANGER BUTTON
   ========================================================= */

.nx-danger-btn {
    display: inline-flex;

    align-items: center;
    justify-content: center;

    gap: 8px;

    border: 0;

    border-radius: 10px;

    background: #d64235;

    color: #ffffff;

    padding: 12px 18px;

    font-size: 13px;

    font-weight: 700;

    cursor: pointer;
}


.nx-danger-btn:hover {
    background: #bd3327;
}


.nx-danger-btn:disabled {
    opacity: 0.7;

    cursor: not-allowed;
}


/* =========================================================
   RESPONSIVE - 1100px
   ========================================================= */

@media (max-width: 1100px) {

    .nx-document-grid {
        grid-template-columns:
            repeat(2, minmax(0, 1fr));
    }

    .nx-documents-page {
        width: 92vw;
    }

}


/* =========================================================
   RESPONSIVE - 850px
   ========================================================= */

@media (max-width: 850px) {

    .nx-toolbar {
        padding-bottom: 45px;

        flex-wrap: wrap;
    }


    .nx-search {
        width: 400px;

        max-width: calc(100% - 100px);

        flex: 1 1 400px;
    }


    .nx-toolbar .nx-document-count {
        top: auto;

        right: 0;

        bottom: 0;

        transform: none;
    }

}


/* =========================================================
   RESPONSIVE - 750px
   ========================================================= */

@media (max-width: 750px) {

    .nx-documents-page {
        width: 100%;

        padding: 20px 15px 40px;
    }


    .nx-hero {
        padding: 28px;

        min-height: auto;
    }


    .nx-hero h1 {
        font-size: 25px;
    }


    .nx-hero-icon {
        display: none;
    }


    .nx-section-header {
        align-items: flex-start;

        flex-direction: column;
    }


    .nx-header-actions {
        width: 100%;
    }


    .nx-upload-btn,
    .nx-refresh-btn {
        flex: 1;
    }


    .nx-document-grid {
        grid-template-columns: 1fr;
    }


    .nx-document-section {
        padding: 0;
    }

}


/* =========================================================
   RESPONSIVE - 600px
   ========================================================= */

@media (max-width: 600px) {

    .nx-toolbar {
        width: 100%;

        display: flex;

        align-items: center;

        justify-content: center;

        flex-wrap: wrap;

        gap: 8px;

        padding: 0 0 45px;

        margin: 20px 0;
    }


    .nx-search {
        width: calc(100% - 90px);

        max-width: none;

        min-width: 0;

        flex: 1 1 auto;
    }


    .nx-search-input {
        height: 42px;

        font-size: 12px;
    }


    .nx-search-btn {
        height: 42px;

        padding: 11px 14px;

        font-size: 12px;
    }


    .nx-toolbar .nx-document-count {
        position: absolute;

        right: 0;

        top: auto;

        bottom: 0;

        transform: none;

        font-size: 11px;
    }


    .nx-card-actions {
        grid-template-columns:
            1fr 1fr 38px;
    }

}


/* =========================================================
   RESPONSIVE - 480px
   ========================================================= */

@media (max-width: 480px) {

    .nx-hero {
        padding: 24px;
    }


    .nx-section-header h2 {
        font-size: 21px;
    }


    .nx-header-actions {
        flex-direction: column;
    }


    .nx-upload-btn,
    .nx-refresh-btn {
        width: 100%;
    }


    .nx-modal-overlay {
        padding: 10px;
    }


    .nx-modal {
        max-height: 96vh;
    }


    .nx-modal-header,
    .nx-modal-body,
    .nx-modal-footer {
        padding-left: 18px;

        padding-right: 18px;
    }

}


/* =========================================================
   RESPONSIVE - VERY SMALL DEVICES
   ========================================================= */

@media (max-width: 420px) {

    .nx-toolbar {
        flex-direction: column;

        align-items: center;

        gap: 10px;

        padding-bottom: 45px;
    }


    .nx-search {
        width: 100%;

        max-width: 100%;

        flex: none;
    }


    .nx-search-btn {
        width: auto;

        min-width: 110px;
    }


    .nx-toolbar .nx-document-count {
        right: 0;

        bottom: 0;
    }


    .nx-card-actions {
        grid-template-columns: 1fr 1fr 36px;

        gap: 6px;

        padding: 10px;
    }

}

sp_widget.script:
(function() {

    /* =========================================================
       CONFIGURATION
       ========================================================= */

    var DOCUMENT_TABLE = "x_snc_college_pl_0_student_document";
    var MAX_FILE_SIZE = 5 * 1024 * 1024;
    var lookupInfo = "";   // filled when the student lookup fails (for debugging)

    /*
     * Possible fields on the STUDENT table that point to sys_user.
     * Add your own field name here if none of these match.
     */
    var STUDENT_USER_FIELDS = ["user", "sys_user", "user_id", "student_user"];


    /* =========================================================
       INITIAL DATA
       ========================================================= */

    data.authorized = true;
    data.studentName = gs.getUserDisplayName() || "Student";
    data.documents = [];
    data.totalDocuments = 0;
    data.uploadSuccess = false;
    data.uploadError = "";
    data.message = "";
    data.newDocumentId = "";
    data.attachmentId = "";
    data.deleteSuccess = false;
    data.deleteError = "";


    /* =========================================================
       MAIN
       ========================================================= */

    if (input && input.action === "save_document") {
        saveDocument();
    } else if (input && input.action === "get_file") {
        getFile();
    } else if (input && input.action === "delete_document") {
        deleteDocument();
    } else {
        // first load and action === "load_documents" (Refresh button)
        loadDocuments();
    }


    /* =========================================================
       GET CURRENT STUDENT
       ========================================================= */

    /* Finds every field on the student table that references sys_user */
    function getUserReferenceFields(studentTable) {

        var names = [];

        try {
            var probe = new GlideRecord(studentTable);
            probe.initialize();

            var fields = probe.getFields();
            var len = fields.size ? fields.size() : fields.length;

            for (var i = 0; i < len; i++) {

                var el = fields.get ? fields.get(i) : fields[i];
                var ref = "";

                try {
                    ref = String(el.getReferenceTable() || "");
                } catch (e) {}

                if (ref === "sys_user") {
                    names.push(String(el.getName()));
                }
            }
        } catch (err) {
            gs.error("NEXORA: could not read student fields: " + err);
        }

        return names;
    }

    function addUnique(list, items) {
        for (var i = 0; i < items.length; i++) {
            if (list.indexOf(items[i]) === -1) {
                list.push(items[i]);
            }
        }
        return list;
    }

    function findStudent(studentTable, fieldNames, value) {

        for (var i = 0; i < fieldNames.length; i++) {

            var gr = new GlideRecord(studentTable);

            if (!gr.isValidField(fieldNames[i])) {
                continue;
            }

            gr.addQuery(fieldNames[i], value);
            gr.setLimit(1);
            gr.query();

            if (gr.next()) {
                return gr;
            }
        }

        return null;
    }

    function getCurrentStudent() {

        var userId = gs.getUserID();

        if (!userId) {
            lookupInfo = "No logged-in user.";
            return null;
        }

        var documentGR = new GlideRecord(DOCUMENT_TABLE);

        if (!documentGR.isValid()) {
            lookupInfo = "Invalid document table " + DOCUMENT_TABLE;
            gs.error("NEXORA: " + lookupInfo);
            return null;
        }

        if (!documentGR.isValidField("student")) {
            lookupInfo = "Field 'student' missing on " + DOCUMENT_TABLE;
            gs.error("NEXORA: " + lookupInfo);
            return null;
        }

        /* Which table does the 'student' field reference? */
        var studentTable = "";

        try {
            studentTable = String(documentGR.getElement("student").getReferenceTable() || "");
        } catch (e1) {}

        if (!studentTable) {
            try {
                studentTable = String(documentGR.getElement("student").getED().getReference() || "");
            } catch (e2) {}
        }

        if (!studentTable) {
            lookupInfo = "Could not find the table referenced by 'student'.";
            gs.error("NEXORA: " + lookupInfo);
            return null;
        }

        /* 1) any field on student table that references sys_user (auto-detected + known names) */
        var userFields = getUserReferenceFields(studentTable);
        addUnique(userFields, STUDENT_USER_FIELDS);

        var found = findStudent(studentTable, userFields, userId);

        if (found) {
            return found;
        }

        /* 2) fallback: match by the user's email */
        var email = gs.getUser().getEmail();
        var emailFields = ["email", "student_email", "college_email", "email_id"];

        if (email) {
            found = findStudent(studentTable, emailFields, email);

            if (found) {
                return found;
            }
        }

        lookupInfo =
            "Student table: " + studentTable +
            " | user fields tried: " + userFields.join(", ");

        gs.error(
            "NEXORA: Student record not found. User: " + userId +
            " | " + lookupInfo
        );

        return null;
    }


    /* =========================================================
       LOAD ALL DOCUMENTS
       ========================================================= */

    function loadDocuments() {

        data.documents = [];
        data.totalDocuments = 0;

        try {

            var studentGR = getCurrentStudent();

            if (!studentGR) {
                data.studentName = gs.getUserDisplayName() || "Student";
                data.message = "Student record was not found for your account. (" + lookupInfo + ")";
                return;
            }

            data.studentName = studentGR.getDisplayValue();

            var documentGR = new GlideRecord(DOCUMENT_TABLE);

            if (!documentGR.isValid()) {
                data.message = "Document table is invalid.";
                return;
            }

            /* Only the current student's documents */
            documentGR.addQuery("student", studentGR.getUniqueValue());

            /* Newest first. Use documentGR.orderBy(...) for oldest first. */
            documentGR.orderByDesc("sys_created_on");

            documentGR.query();

            while (documentGR.next()) {

                var doc = {
                    sysId: documentGR.getUniqueValue(),
                    title: "Untitled Document",
                    documentType: "",
                    description: "",
                    uploadedDate: documentGR.getDisplayValue("sys_created_on"),
                    hasAttachment: false,
                    fileName: "",
                    fileSize: "",
                    fileType: "FILE",
                    previewUrl: "",
                    downloadUrl: ""
                };

                /* Title */
                if (documentGR.isValidField("document_name")) {
                    doc.title = documentGR.getValue("document_name") || "Untitled Document";
                }

                /* Document type */
                if (documentGR.isValidField("document_type")) {
                    doc.documentType =
                        documentGR.getDisplayValue("document_type") ||
                        documentGR.getValue("document_type") ||
                        "";
                }

                /* Description */
                if (documentGR.isValidField("description")) {
                    doc.description = documentGR.getValue("description") || "";
                }

                /* Attachment: only documents that have an uploaded file are shown */
                var att = findAttachment(documentGR);

                if (!att) {
                    continue;
                }

                var attId = att.getUniqueValue();
                var attName = att.getValue("file_name");

                doc.hasAttachment = true;
                doc.fileName = attName;
                doc.fileSize = formatFileSize(att.getValue("size_bytes"));
                doc.fileType = getFileCategory(attName);

                /* view=true asks the server to show the file inline */
                doc.previewUrl = "/sys_attachment.do?sys_id=" + attId + "&view=true";
                doc.downloadUrl = "/sys_attachment.do?sys_id=" + attId;

                data.documents.push(doc);
            }

            data.totalDocuments = data.documents.length;

        } catch (error) {

            gs.error("NEXORA LOAD DOCUMENTS ERROR: " + error);

            data.documents = [];
            data.totalDocuments = 0;
            data.message = "Unable to load documents.";
        }
    }


    /* =========================================================
       SAVE DOCUMENT
       ========================================================= */

    function saveDocument() {

        try {

            data.uploadSuccess = false;
            data.uploadError = "";

            /* Student */
            var studentGR = getCurrentStudent();

            if (!studentGR) {
                data.uploadError = "Student record was not found for the current user. (" + lookupInfo + ")";
                return;
            }

            /* Read input */
            var documentType  = String(input.document_type  || "").trim();
            var documentTitle = documentType;   // the title is the selected / specified document name
            var description   = String(input.description    || "").trim();
            var fileName      = String(input.file_name      || "").trim();
            var contentType   = String(input.file_type       || "").trim();
            var fileData      = String(input.file_data       || "");

            /* Validation */
            if (!documentType) {
                data.uploadError = "Document is required.";
                return;
            }

            if (!description) {
                data.uploadError = "Description is required.";
                return;
            }

            if (!fileName) {
                data.uploadError = "Please select a file.";
                return;
            }

            if (!fileData) {
                data.uploadError = "File data was not received.";
                return;
            }

            /* Allowed file types */
            var allowed = /\.(pdf|jpg|jpeg|png|gif|webp|bmp|doc|docx|xls|xlsx|csv|ppt|pptx|txt)$/i;

            if (!allowed.test(fileName)) {
                data.uploadError = "This file format is not supported.";
                return;
            }

            /* Base64 (strip "data:...;base64," prefix) */
            var base64 = fileData;
            var base64Position = base64.indexOf("base64,");

            if (base64Position !== -1) {
                base64 = base64.substring(base64Position + 7);
            }

            /* File size */
            var estimatedSize = Math.floor((base64.length * 3) / 4);

            if (estimatedSize > MAX_FILE_SIZE) {
                data.uploadError = "File size must not exceed 5 MB.";
                return;
            }

            /* Create document record */
            var documentGR = new GlideRecord(DOCUMENT_TABLE);

            if (!documentGR.isValid()) {
                data.uploadError = "Student Document table is invalid.";
                return;
            }

            /*
             * NOTE: documentGR.canCreate() was removed on purpose.
             * It checks the ACLs of the logged-in user, which was
             * blocking every upload. The student is identified from the
             * logged-in user above, so students can only add documents
             * to their own record.
             */

            documentGR.initialize();

            documentGR.setValue("student", studentGR.getUniqueValue());
            documentGR.setValue("document_name", documentTitle);

            if (documentGR.isValidField("document_type")) {
                documentGR.setValue("document_type", documentType);
            }

            if (documentGR.isValidField("description")) {
                documentGR.setValue("description", description);
            }

            var documentId = documentGR.insert();

            if (!documentId) {
                data.uploadError = "Unable to create document record.";
                return;
            }

            /* Re-fetch inserted record */
            documentGR.get(documentId);

            /* Create attachment */
            var attachment = new GlideSysAttachment();

            var attachmentId = attachment.writeBase64(
                documentGR,
                fileName,
                contentType || "application/octet-stream",
                base64
            );

            if (!attachmentId) {
                documentGR.deleteRecord();
                data.uploadError = "Document was created but the file could not be attached.";
                return;
            }

            /* Save attachment id on the record (if the field exists) */
            if (documentGR.isValidField("document_file")) {
                try {
                    documentGR.setValue("document_file", attachmentId);
                    documentGR.update();
                } catch (fieldError) {
                    gs.error("NEXORA document_file error: " + fieldError);
                }
            }

            /* Success */
            data.uploadSuccess = true;
            data.uploadError = "";
            data.newDocumentId = documentId;
            data.attachmentId = attachmentId;

            /* Reload all documents so the new one is returned immediately */
            loadDocuments();

        } catch (error) {

            gs.error("NEXORA SAVE DOCUMENT ERROR: " + error);

            data.uploadSuccess = false;
            data.uploadError = "Server error while uploading the document.";
        }
    }


    /* =========================================================
       DELETE DOCUMENT
       A student can only delete documents on his / her own record.
       ========================================================= */

    function deleteDocument() {

        data.deleteSuccess = false;
        data.deleteError = "";

        try {

            var studentGR = getCurrentStudent();

            if (!studentGR) {
                data.deleteError = "Student record was not found.";
                return;
            }

            var docId = String(input.doc_id || "");
            var documentGR = new GlideRecord(DOCUMENT_TABLE);

            /* The document must exist AND belong to the logged-in student */
            if (!docId ||
                !documentGR.get(docId) ||
                documentGR.getValue("student") !== studentGR.getUniqueValue()) {

                data.deleteError = "Document not found.";
                return;
            }

            var recordId = documentGR.getUniqueValue();
            var tableName = documentGR.getTableName();

            /* Delete the document record */
            if (!documentGR.deleteRecord()) {
                data.deleteError = "Unable to delete the document.";
                return;
            }

            /* Clean up any file that is still attached to it */
            try {
                var attGR = new GlideRecord("sys_attachment");
                attGR.addQuery("table_name", tableName);
                attGR.addQuery("table_sys_id", recordId);
                attGR.query();

                var sysAttachment = new GlideSysAttachment();

                while (attGR.next()) {
                    sysAttachment.deleteAttachment(attGR.getUniqueValue());
                }
            } catch (cleanupError) {
                gs.error("NEXORA delete attachment cleanup: " + cleanupError);
            }

            data.deleteSuccess = true;

            /* Return the refreshed list */
            loadDocuments();

        } catch (error) {

            gs.error("NEXORA DELETE DOCUMENT ERROR: " + error);
            data.deleteSuccess = false;
            data.deleteError = "Server error while deleting the document.";
        }
    }


    /* =========================================================
       GET FILE CONTENT (used by the Download button)
       The file is read on the server and sent to the browser, so
       it does not depend on attachment ACLs or popup windows.
       ========================================================= */

    function getFile() {

        data.file = null;
        data.fileError = "";

        try {

            var studentGR = getCurrentStudent();

            if (!studentGR) {
                data.fileError = "Student record was not found.";
                return;
            }

            var docId = String(input.doc_id || "");
            var documentGR = new GlideRecord(DOCUMENT_TABLE);

            /* The document must exist AND belong to the logged-in student */
            if (!docId ||
                !documentGR.get(docId) ||
                documentGR.getValue("student") !== studentGR.getUniqueValue()) {

                data.fileError = "Document not found.";
                return;
            }

            var att = findAttachment(documentGR);

            if (!att) {
                data.fileError = "No file is attached to this document.";
                return;
            }

            var base64 = new GlideSysAttachment().getContentBase64(att);

            if (!base64) {
                data.fileError = "The file is empty or could not be read.";
                return;
            }

            data.file = {
                name: att.getValue("file_name"),
                type: att.getValue("content_type") || "application/octet-stream",
                data: base64
            };

        } catch (error) {

            gs.error("NEXORA GET FILE ERROR: " + error);
            data.file = null;
            data.fileError = "Unable to read the file.";
        }
    }


    /* =========================================================
       FIND ATTACHMENT OF A DOCUMENT RECORD
       (returns the sys_attachment GlideRecord, or null)
       ========================================================= */

    function findAttachment(documentGR) {

        var gr = new GlideRecord("sys_attachment");
        gr.addQuery("table_name", documentGR.getTableName());
        gr.addQuery("table_sys_id", documentGR.getUniqueValue());
        gr.orderByDesc("sys_created_on");
        gr.setLimit(1);
        gr.query();

        if (gr.next()) {
            return gr;
        }

        /* Fallback: attachment id stored in the document_file field */
        if (documentGR.isValidField("document_file")) {

            var attId = documentGR.getValue("document_file");

            if (attId) {
                var att = new GlideRecord("sys_attachment");

                if (att.get(attId)) {
                    return att;
                }
            }
        }

        return null;
    }


    /* =========================================================
       FILE CATEGORY
       ========================================================= */

    function getFileCategory(fileName) {

        var name = String(fileName || "").toLowerCase();

        if (/\.pdf$/i.test(name)) {
            return "PDF";
        }

        if (/\.(jpg|jpeg|png|gif|webp|bmp)$/i.test(name)) {
            return "IMAGE";
        }

        if (/\.(doc|docx)$/i.test(name)) {
            return "DOC";
        }

        if (/\.(xls|xlsx|csv)$/i.test(name)) {
            return "XLS";
        }

        if (/\.(ppt|pptx)$/i.test(name)) {
            return "PPT";
        }

        return "FILE";
    }


    /* =========================================================
       FILE SIZE
       ========================================================= */

    function formatFileSize(bytes) {

        var size = parseInt(bytes || 0, 10);

        if (!size) {
            return "";
        }

        if (size < 1024) {
            return size + " B";
        }

        if (size < 1024 * 1024) {
            return Math.round(size / 1024) + " KB";
        }

        return (size / (1024 * 1024)).toFixed(2) + " MB";
    }

})();
